import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.mockito.Mockito.mock;

class AppointmentServiceTest {

    // GreyTest trace: enrichAppointmentResponse | STMT-1 | BR-008 -> TP-004 -> TC-005
    @Test
    void testEnrichAppointmentResponse_IncludesAppointmentAndRelatedDetails() {
        // Arrange
        AppointmentRepository appointmentRepository = mock(AppointmentRepository.class);
        PatientServiceClient patientServiceClient = mock(PatientServiceClient.class);
        DoctorServiceClient doctorServiceClient = mock(DoctorServiceClient.class);
        AppointmentService service = new AppointmentService(appointmentRepository, patientServiceClient, doctorServiceClient);

        Appointment appointment = new Appointment();
        appointment.setId(1001L);
        appointment.setNotes("Ghi chú");
        appointment.setReason("Khám định kỳ");
        appointment.setStatus(Appointment.AppointmentStatus.SCHEDULED);
        appointment.setDoctorId(3001L);
        appointment.setPatientId(2001L);
        appointment.setAppointmentDate(LocalDate.of(2026, 11, 2));
        appointment.setAppointmentTime(LocalTime.of(9, 30));
        appointment.setDiagnosis(null);
        appointment.setPrescription(null);
        appointment.setCreatedAt(null);
        appointment.setUpdatedAt(null);
        appointment.setCancelledAt(null);
        appointment.setCompletedAt(null);

        PatientDto patient = new PatientDto(2001L, "An", "Nguyễn", null, null);
        DoctorDto doctor = new DoctorDto(3001L, "Bình", "Trần", "Tim mạch", true);

        org.mockito.Mockito.when(appointmentRepository.findById(1001L)).thenReturn(java.util.Optional.of(appointment));

        // Act
        AppointmentResponseDto result = service.getAppointmentById(1001L);

        // Assert
        assertEquals(1001L, result.getId());
        assertEquals("Ghi chú", result.getNotes());
        assertEquals("Khám định kỳ", result.getReason());
        assertEquals(Appointment.AppointmentStatus.SCHEDULED, result.getStatus());
        assertEquals(3001L, result.getDoctorId());
        assertEquals(2001L, result.getPatientId());
        assertEquals(LocalDate.of(2026, 11, 2), result.getAppointmentDate());
        assertEquals(LocalTime.of(9, 30), result.getAppointmentTime());
        assertEquals("An Nguyễn", result.getPatientName());
        assertEquals("Dr. Bình Trần", result.getDoctorName());
        assertEquals("Tim mạch", result.getDoctorSpecialization());
        assertNull(result.getDiagnosis());
        assertNull(result.getPrescription());
    }
}
